def comp_graph(inp,out):
 bg=int(inp[0,0]); colors=[int(c) for c in np.unique(inp) if c!=bg]; labmap={}; ndata={}
 for color in colors:
  lab,n=ndimage.label(inp==color,structure=np.ones((3,3)))
  for k in range(1,n+1):
   coords=np.argwhere(lab==k); ident=(color,k); ndata[ident]=coords
   for r,c in coords: labmap[(r,c)]=ident
 adj=defaultdict(set)
 for (r,c),x in labmap.items():
  for dr in (-1,0,1):
   for dc in (-1,0,1):
    if dr==dc==0: continue
    y=labmap.get((r+dr,c+dc))
    if y is not None and y!=x: adj[x].add(y)
 changed=set()
 for id,coords in ndata.items():
